"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21923"],{28367(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.cidade_referencia.uf_incoerente","status":422,"titulo":"UF informada incompat\xedvel com o prefixo do c\xf3digo IBGE"},"descricao":{"codigo":"uniplus.cidade_referencia.uf_incoerente","requisitos":["UNI-REQ-0118"],"oQueAconteceu":["O c\xf3digo IBGE informado tem formato v\xe1lido, mas a **UF** informada n\xe3o \xe9 a\\nque o c\xf3digo designa.","Os dois primeiros d\xedgitos do c\xf3digo IBGE j\xe1 determinam a UF real do\\nmunic\xedpio \u2014 \xe9 um mapa fixo (prefixo \u2192 sigla), o mesmo que a valida\xe7\xe3o usa\\npara conferir se o pr\xf3prio c\xf3digo tem formato v\xe1lido. Nome e UF s\xe3o cache de\\nexibi\xe7\xe3o preenchido pelo cliente, e por isso podem divergir do que o c\xf3digo\\nefetivamente designa; a valida\xe7\xe3o impede que essa diverg\xeancia aconte\xe7a na UF,\\nque faz parte da l\xf3gica de neg\xf3cio derivada do c\xf3digo (feriados estaduais, por\\nexemplo), e n\xe3o apenas do r\xf3tulo exibido.","O **nome** do munic\xedpio, ao contr\xe1rio, n\xe3o passa por esta confer\xeancia de\\ncoer\xeancia: um nome que diverge do munic\xedpio que o c\xf3digo designa \xe9 apenas\\nr\xf3tulo de exibi\xe7\xe3o errado, e a valida\xe7\xe3o n\xe3o o impede."],"comoResolver":["Confira se a UF informada corresponde de fato ao munic\xedpio do c\xf3digo IBGE.\\nNa pr\xe1tica, isso normalmente indica que a UF foi composta ou editada\\nseparadamente do c\xf3digo \u2014 o caminho correto \xe9 escolher o munic\xedpio na lista\\nque o servi\xe7o Geo oferece, deixando c\xf3digo e UF virem juntos e coerentes por\\nconstru\xe7\xe3o, em vez de montar os dois campos de fontes diferentes."],"ondeAparece":["Cadastro ou altera\xe7\xe3o de qualquer entidade que registre cidade por c\xf3digo IBGE","Valida\xe7\xe3o de endere\xe7o (CEP) que carrega o trio de cidade resolvido"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Cidade referencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);